import { Pool, PoolClient, PoolConfig } from 'pg';
import {
  Change, checkChange, Collection, CollectionSpec, decodeToken, encodeToken, fieldPath, Item, keyOf, Page, QueryOptions,
  Range, RecordStore, StorageError,
} from './types';

/**
 * PostgreSQL. One table per collection:
 *
 *   pk text, sk text      the record's key (sk is '' when the collection has no sort key)
 *   data jsonb            the whole record, key fields included, exactly as the other backends return it
 *   expires_at bigint     from the expiry field, generated by the database; expired rows are hidden and purged
 *
 * Key columns and index expressions use COLLATE "C", so strings sort byte by byte, as in DynamoDB.
 * Tables and indexes are created on first use; several services can start at once safely.
 */

type Cursor = [string, string, string];
const NAME = /^[a-z][a-z0-9_]{0,50}$/;
const now = () => Math.floor(Date.now() / 1000);

function ident(name: string): string {
  if (!NAME.test(name)) throw new StorageError(`Unsupported table name: ${name}`);
  return `"${name}"`;
}

/** A JSON field of `data` as text, for keys and indexes. The field name is checked, so it's safe in SQL. */
const textField = (field: string) => `((data->>'${fieldPath(field)[0]}') COLLATE "C")`;

class Sql {
  params: unknown[] = [];
  p(value: unknown): string {
    this.params.push(value);
    return `$${this.params.length}`;
  }
}

function rangeSql(expr: string, range: Range, q: Sql): string {
  if ('between' in range) return `${expr} BETWEEN ${q.p(range.between[0])} AND ${q.p(range.between[1])}`;
  if ('beginsWith' in range) return `starts_with(${expr}, ${q.p(range.beginsWith)})`;
  if ('gte' in range) return `${expr} >= ${q.p(range.gte)}`;
  if ('lte' in range) return `${expr} <= ${q.p(range.lte)}`;
  if ('gt' in range) return `${expr} > ${q.p(range.gt)}`;
  return `${expr} < ${q.p(range.lt)}`;
}

/** SQL for `data` after a change, with its parameters. Mirrors `applyChange`. */
function changedData(change: Change, q: Sql): string {
  let expr = 'data';
  const top: string[] = [];
  const nested = new Map<string, string[]>();
  for (const [path, value] of Object.entries(change.set ?? {})) {
    const [a, b] = fieldPath(path);
    const v = `${q.p(JSON.stringify(value ?? null))}::jsonb`;
    if (b === undefined) top.push(`'${a}', ${v}`);
    else nested.set(a, [...(nested.get(a) ?? []), `'${b}', ${v}`]);
  }
  for (const [field, n] of Object.entries(change.increment ?? {})) {
    const [f] = fieldPath(field);
    top.push(`'${f}', to_jsonb(coalesce((data->>'${f}')::numeric, 0) + ${q.p(n)}::numeric)`);
  }
  if (top.length) expr = `(${expr} || jsonb_build_object(${top.join(', ')}))`;
  for (const [parent, pairs] of nested) {
    const base = `(CASE WHEN jsonb_typeof(data->'${parent}') = 'object' THEN data->'${parent}' ELSE '{}'::jsonb END)`;
    expr = `(${expr} || jsonb_build_object('${parent}', ${base} || jsonb_build_object(${pairs.join(', ')})))`;
  }
  for (const path of change.remove ?? []) expr = `(${expr} #- ${q.p(fieldPath(path))}::text[])`;
  return expr;
}

class PgCollection<T extends object> implements Collection<T> {
  private table: string;
  constructor(readonly spec: CollectionSpec, private store: PostgresStore, prefix: string) {
    this.table = ident(`${prefix}${spec.name}`);
  }

  private ready() {
    return this.store.ensure(this.spec, this.table);
  }

  private live(q: Sql) {
    return `(expires_at IS NULL OR expires_at > ${q.p(now())})`;
  }

  async get(key: Item) {
    await this.ready();
    const { pk, sk } = keyOf(this.spec, key);
    const q = new Sql();
    const r = await this.store.pool.query(`SELECT data FROM ${this.table} WHERE pk = ${q.p(pk)} AND sk = ${q.p(sk)} AND ${this.live(q)}`, q.params);
    return (r.rows[0]?.data ?? null) as T | null;
  }

  async put(item: T, options: { ifNotExists?: boolean } = {}) {
    await this.ready();
    const { pk, sk } = keyOf(this.spec, item as Item);
    const q = new Sql();
    const values = `(${q.p(pk)}, ${q.p(sk)}, ${q.p(JSON.stringify(item))}::jsonb)`;
    // With ifNotExists, an expired record counts as gone and is replaced.
    const onConflict = options.ifNotExists
      ? `DO UPDATE SET data = EXCLUDED.data WHERE ${this.table}.expires_at IS NOT NULL AND ${this.table}.expires_at <= ${q.p(now())}`
      : 'DO UPDATE SET data = EXCLUDED.data';
    const r = await this.store.pool.query(`INSERT INTO ${this.table} (pk, sk, data) VALUES ${values} ON CONFLICT (pk, sk) ${onConflict}`, q.params);
    return (r.rowCount ?? 0) > 0;
  }

  async update(key: Item, change: Change) {
    checkChange(this.spec, change);
    await this.ready();
    const { pk, sk } = keyOf(this.spec, key);
    const keyRecord = { [this.spec.partitionKey]: pk, ...(this.spec.sortKey ? { [this.spec.sortKey]: sk } : {}) };
    return this.store.transaction(async (c) => {
      if (!change.ifExists) {
        // Create the record (or replace an expired one) so the update below always has a row to change.
        const q = new Sql();
        await c.query(
          `INSERT INTO ${this.table} (pk, sk, data) VALUES (${q.p(pk)}, ${q.p(sk)}, ${q.p(JSON.stringify(keyRecord))}::jsonb)
           ON CONFLICT (pk, sk) DO UPDATE SET data = EXCLUDED.data
           WHERE ${this.table}.expires_at IS NOT NULL AND ${this.table}.expires_at <= ${q.p(now())}`,
          q.params,
        );
      }
      const q = new Sql();
      const data = changedData(change, q);
      const r = await c.query(
        `UPDATE ${this.table} SET data = ${data} WHERE pk = ${q.p(pk)} AND sk = ${q.p(sk)} AND ${this.live(q)} RETURNING data`,
        q.params,
      );
      return (r.rows[0]?.data ?? null) as T | null;
    });
  }

  async delete(key: Item) {
    await this.ready();
    const { pk, sk } = keyOf(this.spec, key);
    await this.store.pool.query(`DELETE FROM ${this.table} WHERE pk = $1 AND sk = $2`, [pk, sk]);
  }

  async query(o: QueryOptions): Promise<Page<T>> {
    await this.ready();
    const idx = o.index ? this.spec.indexes?.[o.index] : undefined;
    if (o.index && !idx) throw new StorageError(`${this.spec.name}: no index ${o.index}`);
    const pkExpr = idx ? textField(idx.partitionKey) : 'pk';
    const skField = idx ? idx.sortKey : this.spec.sortKey;
    const skExpr = idx ? (idx.sortKey ? textField(idx.sortKey) : `''::text`) : 'sk';
    const hasSort = idx ? !!idx.sortKey : true;
    const q = new Sql();
    const where = [`${pkExpr} = ${q.p(o.partition)}`, this.live(q)];
    if (idx?.sortKey) where.push(`${skExpr} IS NOT NULL`); // records without the field aren't in the index
    if (o.range) {
      if (!skField) throw new StorageError(`${this.spec.name}: a range needs a sort key`);
      where.push(rangeSql(skExpr, o.range, q));
    }
    const desc = o.order === 'desc';
    if (o.after) {
      const [s, p, k] = decodeToken<Cursor>(o.after);
      where.push(`(${skExpr}, pk, sk) ${desc ? '<' : '>'} (${q.p(s)}, ${q.p(p)}, ${q.p(k)})`);
    }
    const dir = desc ? 'DESC' : 'ASC';
    const limit = o.limit && o.limit > 0 ? o.limit : undefined;
    const r = await this.store.pool.query(
      `SELECT data, ${skExpr} AS s, pk, sk FROM ${this.table} WHERE ${where.join(' AND ')}
       ORDER BY ${hasSort ? `${skExpr} ${dir}, ` : ''}pk ${dir}, sk ${dir}${limit ? ` LIMIT ${q.p(limit + 1)}` : ''}`,
      q.params,
    );
    return this.page(r.rows, limit);
  }

  async scan(o: { limit?: number; after?: string } = {}): Promise<Page<T>> {
    await this.ready();
    const q = new Sql();
    const where = [this.live(q)];
    if (o.after) {
      const [, p, k] = decodeToken<Cursor>(o.after);
      where.push(`(pk, sk) > (${q.p(p)}, ${q.p(k)})`);
    }
    const limit = o.limit && o.limit > 0 ? o.limit : undefined;
    const r = await this.store.pool.query(
      `SELECT data, '' AS s, pk, sk FROM ${this.table} WHERE ${where.join(' AND ')} ORDER BY pk, sk${limit ? ` LIMIT ${q.p(limit + 1)}` : ''}`,
      q.params,
    );
    return this.page(r.rows, limit);
  }

  private page(rows: Array<{ data: T; s: string; pk: string; sk: string }>, limit?: number): Page<T> {
    const more = limit !== undefined && rows.length > limit;
    const page = more ? rows.slice(0, limit) : rows;
    const last = page[page.length - 1];
    return { items: page.map((r) => r.data), ...(more && last ? { next: encodeToken([last.s ?? '', last.pk, last.sk]) } : {}) };
  }
}

export interface PostgresOptions {
  /** postgres://user:password@host:5432/db — `?sslmode=require` turns on TLS. */
  connectionString?: string;
  /** Prefix for table names, e.g. `probaline_`. */
  tablePrefix?: string;
  pool?: Pool;
  poolConfig?: PoolConfig;
  /** How often expired records are deleted. Default: hourly. 0 turns it off. */
  purgeEverySeconds?: number;
}

export class PostgresStore implements RecordStore {
  readonly kind = 'postgres' as const;
  readonly pool: Pool;
  private prefix: string;
  private ensured = new Map<string, Promise<void>>();
  private expiring = new Set<string>();
  private timer?: NodeJS.Timeout;

  constructor(options: PostgresOptions = {}) {
    this.prefix = options.tablePrefix ?? '';
    if (this.prefix && !/^[a-z][a-z0-9_]*$/.test(this.prefix)) throw new StorageError('tablePrefix must be lower case letters, digits and underscores');
    this.pool = options.pool ?? new Pool({ connectionString: options.connectionString, max: 10, ...options.poolConfig });
    // An idle connection that drops (database restart) must not crash the service.
    this.pool.on('error', () => undefined);
    const every = options.purgeEverySeconds ?? 3600;
    if (every > 0) {
      this.timer = setInterval(() => { void this.purgeExpired().catch(() => undefined); }, every * 1000);
      this.timer.unref();
    }
  }

  collection<T extends object = Item>(spec: CollectionSpec): Collection<T> {
    return new PgCollection<T>(spec, this, this.prefix);
  }

  /** Create the collection's table and indexes once per process. */
  ensure(spec: CollectionSpec, table: string): Promise<void> {
    let p = this.ensured.get(table);
    if (!p) {
      p = this.createTable(spec, table).catch((err) => { this.ensured.delete(table); throw err; });
      this.ensured.set(table, p);
    }
    return p;
  }

  private async createTable(spec: CollectionSpec, table: string) {
    const raw = table.slice(1, -1);
    const expires = spec.ttlField
      ? `bigint GENERATED ALWAYS AS (CASE WHEN jsonb_typeof(data->'${fieldPath(spec.ttlField)[0]}') = 'number' THEN floor((data->>'${fieldPath(spec.ttlField)[0]}')::numeric)::bigint END) STORED`
      : 'bigint';
    const statements = [
      `CREATE TABLE IF NOT EXISTS ${table} (
         pk text COLLATE "C" NOT NULL,
         sk text COLLATE "C" NOT NULL DEFAULT '',
         data jsonb NOT NULL,
         expires_at ${expires},
         PRIMARY KEY (pk, sk))`,
      `CREATE INDEX IF NOT EXISTS ${ident(`${raw}_expires`)} ON ${table} (expires_at) WHERE expires_at IS NOT NULL`,
    ];
    for (const [name, idx] of Object.entries(spec.indexes ?? {})) {
      const idxName = ident(`${raw}_ix_${name.toLowerCase().replace(/[^a-z0-9]+/g, '_')}`.slice(0, 60));
      const cols = [textField(idx.partitionKey), ...(idx.sortKey ? [textField(idx.sortKey)] : []), 'pk', 'sk'];
      statements.push(`CREATE INDEX IF NOT EXISTS ${idxName} ON ${table} (${cols.join(', ')})`);
    }
    await this.transaction(async (c) => {
      // Two services creating the same table at once would collide; take a lock for the schema change.
      await c.query(`SELECT pg_advisory_xact_lock(hashtext('probaline_schema'))`);
      for (const s of statements) await c.query(s);
    });
    if (spec.ttlField) this.expiring.add(table);
  }

  async transaction<R>(fn: (c: PoolClient) => Promise<R>): Promise<R> {
    const c = await this.pool.connect();
    try {
      await c.query('BEGIN');
      const out = await fn(c);
      await c.query('COMMIT');
      return out;
    } catch (err) {
      await c.query('ROLLBACK').catch(() => undefined);
      throw err;
    } finally {
      c.release();
    }
  }

  /** Delete expired records now. Reads already hide them; this frees the space. */
  async purgeExpired(): Promise<number> {
    let n = 0;
    for (const table of this.expiring) {
      const r = await this.pool.query(`DELETE FROM ${table} WHERE expires_at IS NOT NULL AND expires_at <= $1`, [now()]);
      n += r.rowCount ?? 0;
    }
    return n;
  }

  async ping() {
    await this.pool.query('SELECT 1');
  }

  async close() {
    if (this.timer) clearInterval(this.timer);
    await this.pool.end();
  }
}
